def count_inversions(arr):
    """
    Counts the number of inversions in an array.
    Parameters:
        arr (list): The input array.
    Returns:
        int: The number of inversions.
    """

    def merge_count_split_inv(left, right):
        result = []
        left_index, right_index = (0, 0)
        split_inv = 0
        while left_index < len(left) and right_index < len(right):
            if left[left_index] <= right[right_index]:
                result.append(left[left_index])
                left_index += 1
            else:
                result.append(right[right_index])
                split_inv += len(left) - left_index
                right_index += 1
        result.extend(left[left_index:])
        result.extend(right[right_index:])
        return (result, split_inv)

    def sort_count_inversions(arr):
        if len(arr) <= 1:
            return (arr, 0)
        mid = len(arr) // 2
        left, x = sort_count_inversions(arr[:mid])
        right, y = sort_count_inversions(arr[mid:])
        merged, z = merge_count_split_inv(left, right)
        return (merged, x + y + z)
    _, inversions = sort_count_inversions(arr)
    return inversions

