def max_divisible_subset_size(numbers):
    """
    Finds the size of the largest subset where each pair of elements (a, b) satisfies a % b == 0 or b % a == 0.
    :param numbers: List[int] - A list of positive integers.
    :return: int - The size of the largest divisible subset.
    """
    if not numbers:
        return 0
    numbers.sort()
    dp = [1] * len(numbers)
    for i in range(len(numbers)):
        for j in range(i):
            if numbers[i] % numbers[j] == 0 and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
    return max(dp)

