def longest_repeating_subsequence(s):
    n = len(s)
    m = [[0 for _ in range(n + 1)] for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if s[i - 1] == s[j - 1] and i != j:
                m[i][j] = 1 + m[i - 1][j - 1]
            else:
                m[i][j] = max(m[i - 1][j], m[i][j - 1])
    return m[n][n]

